mapper.select:
select * from a2a_requests where tenant_id=#{tenantId} and request_status=#{requestStatus}
and (a2a_request_id ilike concat('%',#{text},'%') or root_task_id ilike concat('%',#{text},'%') or source_task_id ilike concat('%',#{text},'%') or child_task_id ilike concat('%',#{text},'%') or target_domain_id ilike concat('%',#{text},'%') or requested_task_type ilike concat('%',#{text},'%') or operational_stage ilike concat('%',#{text},'%') or blocker_code ilike concat('%',#{text},'%'))
order by updated_at desc nulls last, created_at desc limit #{limit}
